import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"41 - MCP Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/41-mcp-architecture.md","filePath":"developers/design-documentation/41-mcp-architecture.md"}'),s={name:"developers/design-documentation/41-mcp-architecture.md"};function d(i,e,n,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="_41-mcp-architecture" tabindex="-1">41 - MCP Architecture <a class="header-anchor" href="#_41-mcp-architecture" aria-label="Permalink to &quot;41 - MCP Architecture&quot;">​</a></h1><h2 id="transports" tabindex="-1">Transports <a class="header-anchor" href="#transports" aria-label="Permalink to &quot;Transports&quot;">​</a></h2><p>Tradeboard has two MCP deployment modes:</p><table tabindex="0"><thead><tr><th>Transport</th><th>Entry</th><th>Registration</th><th>Auth</th></tr></thead><tbody><tr><td>Local stdio</td><td><code>mcp/mcpserver.py</code></td><td>Spawned by a desktop/client config</td><td>Tradeboard API key and host passed to local process</td></tr><tr><td>Remote HTTP/SSE</td><td><code>blueprints/mcp_http.py</code></td><td>Opt-in during Flask startup</td><td>OAuth 2.1 access token and scopes</td></tr></tbody></table><p>Both modes expose trading and research tools backed by Tradeboard services/SDK behavior. The Python application currently pins the Tradeboard SDK at <code>2.0.3</code>.</p><h2 id="local-stdio" tabindex="-1">Local Stdio <a class="header-anchor" href="#local-stdio" aria-label="Permalink to &quot;Local Stdio&quot;">​</a></h2><p>The MCP client launches <code>.venv/bin/python mcp/mcpserver.py &lt;api-key&gt; &lt;host&gt;</code> (Windows uses the equivalent interpreter path). It communicates over stdio and calls the configured Tradeboard host. The API key should be scoped to the local self-hosted installation and protected as a secret in client configuration.</p><p><code>mcp/README.md</code> contains client path examples and the current tool list.</p><h2 id="remote-gate" tabindex="-1">Remote Gate <a class="header-anchor" href="#remote-gate" aria-label="Permalink to &quot;Remote Gate&quot;">​</a></h2><p>Remote MCP is disabled by default. <code>app.py</code> registers the OAuth and MCP blueprints only when all startup requirements pass:</p><ul><li><code>MCP_HTTP_ENABLED=True</code>.</li><li>Flask debug is disabled.</li><li><code>MCP_PUBLIC_URL</code> is configured as the canonical public origin.</li><li>The guarded boot marker is set before importing transport modules.</li></ul><p>This conditional surface is included in static route discovery but is absent from a default runtime URL map.</p><h2 id="oauth-model" tabindex="-1">OAuth Model <a class="header-anchor" href="#oauth-model" aria-label="Permalink to &quot;OAuth Model&quot;">​</a></h2><p><code>blueprints/mcp_oauth.py</code> implements discovery, protected-resource metadata, JWKS, dynamic client registration, authorization, token, refresh, and revocation behavior. OAuth data is stored by <code>database/oauth_db.py</code> in the main database.</p><p>Supported scopes are:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Capability</th></tr></thead><tbody><tr><td><code>read:market</code></td><td>Quotes, depth, history, instruments and research data</td></tr><tr><td><code>read:account</code></td><td>Orders, trades, positions, holdings, funds</td></tr><tr><td><code>write:orders</code></td><td>Place, modify, cancel, and close trading actions</td></tr></tbody></table><p><code>write:orders</code> is advertised only when <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=True</code>. Consent can require a fresh TOTP verification. Dynamic clients can require admin approval through <code>MCP_OAUTH_REQUIRE_APPROVAL</code>.</p><h2 id="remote-request-flow" tabindex="-1">Remote Request Flow <a class="header-anchor" href="#remote-request-flow" aria-label="Permalink to &quot;Remote Request Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hosted MCP client</span></span>
<span class="line"><span>  -&gt; OAuth discovery / registration</span></span>
<span class="line"><span>  -&gt; local-user consent (and fresh TOTP for write when configured)</span></span>
<span class="line"><span>  -&gt; authorization-code + PKCE token exchange</span></span>
<span class="line"><span>  -&gt; bearer token with scopes</span></span>
<span class="line"><span>  -&gt; /mcp JSON-RPC or SSE transport</span></span>
<span class="line"><span>  -&gt; scoped tool dispatch</span></span>
<span class="line"><span>  -&gt; Tradeboard service/API behavior</span></span></code></pre></div><p>The public origin anchors issuer/audience behavior. Production exposure requires HTTPS, a restricted CORS allowlist, strong signing keys, and deliberate write/approval settings.</p><h2 id="admin-controls" tabindex="-1">Admin Controls <a class="header-anchor" href="#admin-controls" aria-label="Permalink to &quot;Admin Controls&quot;">​</a></h2><p>The admin surface provides OAuth client review, MCP settings/audit data, and a kill switch. Startup logs explicitly warn when write access is enabled or client approval is disabled.</p><h2 id="security-invariants" tabindex="-1">Security Invariants <a class="header-anchor" href="#security-invariants" aria-label="Permalink to &quot;Security Invariants&quot;">​</a></h2><ul><li>Do not enable Remote MCP in Flask debug mode.</li><li>Never grant a requested scope that was not advertised and enabled.</li><li>Require redirect URI exactness and PKCE for public clients.</li><li>Keep local app authentication and OAuth client authentication separate.</li><li>Keep order tools behind <code>write:orders</code>; read tokens cannot execute trades.</li><li>Treat the self-hosted server and static broker-IP controls as additional deployment boundaries, not substitutes for OAuth checks.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>mcp/mcpserver.py</code></td><td>Local stdio server</td></tr><tr><td><code>utils/mcp_tool_registry.py</code></td><td>Shared tool registration helpers</td></tr><tr><td><code>blueprints/mcp_http.py</code></td><td>Remote MCP transport/dispatch</td></tr><tr><td><code>blueprints/mcp_oauth.py</code></td><td>OAuth authorization server</td></tr><tr><td><code>database/oauth_db.py</code></td><td>Clients, grants/tokens, audit/control state</td></tr><tr><td><code>app.py</code></td><td>Opt-in startup gate and warnings</td></tr></tbody></table>`,26)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
